#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <OpenCL/opencl.h>
#include <openssl/sha.h>

static const char *src =
"__constant uint K[64] = {\n"
"0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,\n"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,\n"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,\n"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,\n"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};\n"
"#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))\n"
"#define CH(x,y,z) (((x)&(y))^((~(x))&(z)))\n"
"#define MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))\n"
"#define BSIG0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))\n"
"#define BSIG1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))\n"
"#define SSIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))\n"
"#define SSIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))\n"
"__kernel void sha256_blocks(__global const uchar *data, uint nblocks, __global uint *states) {\n"
"  uint gid = get_global_id(0);\n"
"  if (gid >= nblocks) return;\n"
"  __global const uchar *blk = data + ((size_t)gid << 6);\n"
"  uint w[64];\n"
"  for (int i = 0; i < 16; i++) {\n"
"    w[i] = ((uint)blk[i*4]<<24)|((uint)blk[i*4+1]<<16)|((uint)blk[i*4+2]<<8)|((uint)blk[i*4+3]);\n"
"  }\n"
"  for (int i = 16; i < 64; i++) w[i] = w[i-16] + SSIG0(w[i-15]) + w[i-7] + SSIG1(w[i-2]);\n"
"  uint a=0x6a09e667,b=0xbb67ae85,c=0x3c6ef372,d=0xa54ff53a;\n"
"  uint e=0x510e527f,f=0x9b05688c,g=0x1f83d9ab,h=0x5be0cd19;\n"
"  for (int i = 0; i < 64; i++) {\n"
"    uint t1 = h + BSIG1(e) + CH(e,f,g) + K[i] + w[i];\n"
"    uint t2 = BSIG0(a) + MAJ(a,b,c);\n"
"    h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;\n"
"  }\n"
"  __global uint *s = states + gid*8;\n"
"  s[0]=a+0x6a09e667; s[1]=b+0xbb67ae85; s[2]=c+0x3c6ef372; s[3]=d+0xa54ff53a;\n"
"  s[4]=e+0x510e527f; s[5]=f+0x9b05688c; s[6]=g+0x1f83d9ab; s[7]=h+0x5be0cd19;\n"
"}\n";

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
static void check(cl_int e, const char *w){ if(e!=CL_SUCCESS){fprintf(stderr,"err %s %d\n", w, e); exit(1);} }

int main() {
    cl_platform_id plat; clGetPlatformIDs(1, &plat, NULL);
    cl_device_id devs[8]; cl_uint nd=0;
    clGetDeviceIDs(plat, CL_DEVICE_TYPE_GPU, 8, devs, &nd);
    cl_device_id dev = devs[nd-1]; // prefer last GPU (AMD)
    char name[256]={0};
    clGetDeviceInfo(dev, CL_DEVICE_NAME, sizeof(name), name, NULL);
    printf("using %s\n", name);

    cl_int err;
    cl_context ctx = clCreateContext(NULL, 1, &dev, NULL, NULL, &err); check(err,"ctx");
    cl_command_queue q = clCreateCommandQueue(ctx, dev, 0, &err); check(err,"q");
    cl_program prog = clCreateProgramWithSource(ctx, 1, &src, NULL, &err); check(err,"prog");
    err = clBuildProgram(prog, 1, &dev, "-cl-fast-relaxed-math", NULL, NULL);
    if (err != CL_SUCCESS) {
        size_t logsz; clGetProgramBuildInfo(prog, dev, CL_PROGRAM_BUILD_LOG, 0, NULL, &logsz);
        char *log = malloc(logsz+1);
        clGetProgramBuildInfo(prog, dev, CL_PROGRAM_BUILD_LOG, logsz, log, NULL);
        fprintf(stderr, "build fail:\n%s\n", log);
        return 1;
    }
    cl_kernel k = clCreateKernel(prog, "sha256_blocks", &err); check(err,"k");

    size_t nbytes = 20ull*1024*1024;
    // multiple of 64
    size_t nblocks = nbytes / 64;
    uint8_t *data = malloc(nbytes);
    memset(data, 0x5a, nbytes);
    uint32_t *states = malloc(nblocks * 8 * sizeof(uint32_t));

    cl_mem d_data = clCreateBuffer(ctx, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, nbytes, data, &err); check(err,"buf");
    cl_mem d_states = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, nblocks*8*sizeof(uint32_t), NULL, &err); check(err,"st");

    clSetKernelArg(k, 0, sizeof(cl_mem), &d_data);
    clSetKernelArg(k, 1, sizeof(cl_uint), &(cl_uint){(cl_uint)nblocks});
    // nblocks may exceed 32-bit? 20MB/64 = 327680, fine. But pass as uint.
    cl_uint nb = (cl_uint)nblocks;
    clSetKernelArg(k, 1, sizeof(cl_uint), &nb);
    clSetKernelArg(k, 2, sizeof(cl_mem), &d_states);

    size_t g = nblocks;
    // warmup
    err = clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL); check(err,"enq");
    clFinish(q);
    double t0 = now();
    int reps = 5;
    for (int i = 0; i < reps; i++) {
        clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
    }
    clFinish(q);
    double t1 = now();
    printf("kernel only: %.4f s  %.1f MB/s\n", (t1-t0)/reps, nbytes/((t1-t0)/reps)/1e6);

    // with transfer
    t0 = now();
    for (int i = 0; i < reps; i++) {
        clEnqueueWriteBuffer(q, d_data, CL_FALSE, 0, nbytes, data, 0, NULL, NULL);
        clEnqueueNDRangeKernel(q, k, 1, NULL, &g, NULL, 0, NULL, NULL);
        clEnqueueReadBuffer(q, d_states, CL_FALSE, 0, nblocks*8*sizeof(uint32_t), states, 0, NULL, NULL);
    }
    clFinish(q);
    t1 = now();
    printf("with xfer states: %.4f s  %.1f MB/s\n", (t1-t0)/reps, nbytes/((t1-t0)/reps)/1e6);

    // verify one block
    uint8_t block[64]; memset(block, 0x5a, 64);
    uint8_t out[32];
    // hash single block via openssl of 64 bytes? not the same as intermediate state.
    // Just print first state
    clEnqueueReadBuffer(q, d_states, CL_TRUE, 0, 32, states, 0, NULL, NULL);
    printf("state0:");
    for (int i = 0; i < 8; i++) printf(" %08x", states[i]);
    printf("\n");
    SHA256(block, 64, out); // this includes padding, not comparable
    printf("(openssl of 64B with pad not comparable)\n");
    return 0;
}
EOF
