#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
#include <dlfcn.h>
#include <time.h>

typedef struct { uint32_t A[8],B[8],C[8],D[8],E[8],F[8],G[8],H[8]; } SOA;
typedef struct { const unsigned char *ptr; int blocks; } DATA;
typedef void (*mb_fn)(void*, const void*, int);

static void compress_ref(uint32_t st[8], const uint8_t block[64]) {
    SHA256_CTX ctx;
    memcpy(ctx.h, st, 32);
    // SHA256_CTX.h is the state. Transform adds.
    // But SHA256_CTX may have different layout. Safer to use a known software compress.
    // We'll just use openssl by setting ctx.h and Nl etc.
    SHA256_Init(&ctx);
    memcpy(ctx.h, st, 32);
    SHA256_Transform(&ctx, block);
    memcpy(st, ctx.h, 32);
}

int main() {
    void *h = dlopen("/usr/local/Cellar/openssl@3/3.6.5/lib/libcrypto.3.dylib", RTLD_NOW);
    mb_fn fn = (mb_fn)dlsym(h, "sha256_multi_block");

    // 8*64 = 512 bytes message of distinct bytes
    uint8_t msg[512];
    for (int i = 0; i < 512; i++) msg[i] = (uint8_t)i;

    // Reference: sequential compress of 8 blocks
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for (int b = 0; b < 8; b++) compress_ref(st, msg + b*64);
    printf("seq:");
    for (int i = 0; i < 8; i++) printf(" %08x", st[i]);
    printf("\n");

    // Interleaved: lane L gets block L (only 1 block each) — this is NOT sequential chaining
    // That's what we already know works for independent streams.
    // What we need: can we feed block0 to all lanes? No that doesn't chain.

    // Idea: use multi_block as 8 independent compressions of blocks 0..7 starting from SAME iv,
    // then somehow combine. That is NOT sha256. So Merkle, not sha256.

    // Confirm blocks field: if we pass 8 consecutive blocks in one lane, state chains.
    SOA soa;
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for (int l=0;l<8;l++){soa.A[l]=iv[0];soa.B[l]=iv[1];soa.C[l]=iv[2];soa.D[l]=iv[3];soa.E[l]=iv[4];soa.F[l]=iv[5];soa.G[l]=iv[6];soa.H[l]=iv[7];}
    DATA d[8];
    for (int l=0;l<8;l++){ d[l].ptr = msg; d[l].blocks = 8; } // all lanes same 8 blocks
    fn(&soa, d, 1); // only lane 0
    printf("lane0 8blocks:");
    printf(" %08x %08x ... match seq A %d\n", soa.A[0], soa.B[0], soa.A[0]==st[0] && soa.H[0]==st[7]);

    // Interleave experiment: split message into 8 streams of every 8th block, hash independently, see if any simple combo equals sequential.
    // This is just to document it doesn't.
    uint8_t streams[8][64];
    for (int b = 0; b < 8; b++) memcpy(streams[b], msg+b*64, 64);
    for (int l=0;l<8;l++){soa.A[l]=iv[0];soa.B[l]=iv[1];soa.C[l]=iv[2];soa.D[l]=iv[3];soa.E[l]=iv[4];soa.F[l]=iv[5];soa.G[l]=iv[6];soa.H[l]=iv[7];
        d[l].ptr = streams[l]; d[l].blocks = 1;}
    fn(&soa, d, 8);
    printf("indep lane0 A=%08x seq A=%08x (should differ)\n", soa.A[0], st[0]);

    // XOR of lane states vs seq
    uint32_t xA=0,xB=0,xC=0,xD=0,xE=0,xF=0,xG=0,xH=0;
    xA=soa.A[0]^soa.A[1]^soa.A[2]^soa.A[3]^soa.A[4]^soa.A[5]^soa.A[6]^soa.A[7];
    printf("xor A=%08x seq A=%08x\n", xA, st[0]);
    return 0;
}
EOF
