// 8-way interleaved SHA-256 using AVX2. Each lane is an independent message.
// For a single message we cannot chain, but we benchmark independent lanes
// and also a "fake" single-stream schedule to see raw compression throughput.
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <immintrin.h>
#include <openssl/sha.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline __m256i rotr(__m256i x, int n) {
    return _mm256_or_si256(_mm256_srli_epi32(x, n), _mm256_slli_epi32(x, 32-n));
}

// Process 8 independent 64-byte blocks, one per lane. state[8] are __m256i A..H
static void sha256_8way(uint32_t state[8][8], const uint8_t blocks[8][64]) {
    __m256i A = _mm256_loadu_si256((const __m256i*)state[0]);
    __m256i B = _mm256_loadu_si256((const __m256i*)state[1]);
    __m256i C = _mm256_loadu_si256((const __m256i*)state[2]);
    __m256i D = _mm256_loadu_si256((const __m256i*)state[3]);
    __m256i E = _mm256_loadu_si256((const __m256i*)state[4]);
    __m256i F = _mm256_loadu_si256((const __m256i*)state[5]);
    __m256i G = _mm256_loadu_si256((const __m256i*)state[6]);
    __m256i H = _mm256_loadu_si256((const __m256i*)state[7]);
    __m256i A0=A,B0=B,C0=C,D0=D,E0=E,F0=F,G0=G,H0=H;

    // Load W[0..15] for 8 lanes. blocks layout: lane-major.
    // Transpose 8x16 uint32 from lane-major to round-major.
    uint32_t wtmp[16][8];
    for (int lane = 0; lane < 8; lane++) {
        const uint8_t *b = blocks[lane];
        for (int i = 0; i < 16; i++) {
            wtmp[i][lane] = ((uint32_t)b[i*4]<<24)|((uint32_t)b[i*4+1]<<16)|((uint32_t)b[i*4+2]<<8)|b[i*4+3];
        }
    }
    __m256i W[64];
    for (int i = 0; i < 16; i++) W[i] = _mm256_loadu_si256((const __m256i*)wtmp[i]);
    for (int i = 16; i < 64; i++) {
        __m256i w15 = W[i-15];
        __m256i s0 = _mm256_xor_si256(rotr(w15,7), _mm256_xor_si256(rotr(w15,18), _mm256_srli_epi32(w15,3)));
        __m256i w2 = W[i-2];
        __m256i s1 = _mm256_xor_si256(rotr(w2,17), _mm256_xor_si256(rotr(w2,19), _mm256_srli_epi32(w2,10)));
        W[i] = _mm256_add_epi32(_mm256_add_epi32(W[i-16], s0), _mm256_add_epi32(W[i-7], s1));
    }
    for (int i = 0; i < 64; i++) {
        __m256i S1 = _mm256_xor_si256(rotr(E,6), _mm256_xor_si256(rotr(E,11), rotr(E,25)));
        __m256i ch = _mm256_xor_si256(_mm256_and_si256(E,F), _mm256_andnot_si256(E,G));
        __m256i t1 = _mm256_add_epi32(H, _mm256_add_epi32(S1, _mm256_add_epi32(ch, _mm256_add_epi32(_mm256_set1_epi32(K[i]), W[i]))));
        __m256i S0 = _mm256_xor_si256(rotr(A,2), _mm256_xor_si256(rotr(A,13), rotr(A,22)));
        __m256i maj = _mm256_xor_si256(_mm256_and_si256(A,B), _mm256_xor_si256(_mm256_and_si256(A,C), _mm256_and_si256(B,C)));
        __m256i t2 = _mm256_add_epi32(S0, maj);
        H=G; G=F; F=E; E=_mm256_add_epi32(D,t1); D=C; C=B; B=A; A=_mm256_add_epi32(t1,t2);
    }
    A=_mm256_add_epi32(A,A0); B=_mm256_add_epi32(B,B0); C=_mm256_add_epi32(C,C0); D=_mm256_add_epi32(D,D0);
    E=_mm256_add_epi32(E,E0); F=_mm256_add_epi32(F,F0); G=_mm256_add_epi32(G,G0); H=_mm256_add_epi32(H,H0);
    _mm256_storeu_si256((__m256i*)state[0], A);
    _mm256_storeu_si256((__m256i*)state[1], B);
    _mm256_storeu_si256((__m256i*)state[2], C);
    _mm256_storeu_si256((__m256i*)state[3], D);
    _mm256_storeu_si256((__m256i*)state[4], E);
    _mm256_storeu_si256((__m256i*)state[5], F);
    _mm256_storeu_si256((__m256i*)state[6], G);
    _mm256_storeu_si256((__m256i*)state[7], H);
}

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

int main() {
    size_t nblocks = (20ull*1024*1024)/64; // per lane
    size_t nbytes = nblocks * 64;
    uint8_t *data = aligned_alloc(64, 8 * nbytes);
    memset(data, 0x5a, 8*nbytes);
    uint32_t state[8][8];
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    // correctness: 1 block
    for (int i=0;i<8;i++) for (int l=0;l<8;l++) state[i][l]=iv[i];
    uint8_t blk[8][64];
    for (int l=0;l<8;l++) { memset(blk[l], 0x5a, 64); blk[l][0]=(uint8_t)l; }
    sha256_8way(state, blk);
    SHA256_CTX ctx; SHA256_Init(&ctx); SHA256_Transform(&ctx, blk[3]);
    printf("lane3 A=%08x ref=%08x match=%d\n", state[0][3], ctx.h[0], state[0][3]==ctx.h[0]);

    // bench
    int reps=2;
    double t0=now();
    for (int r=0;r<reps;r++) {
        for (int i=0;i<8;i++) for (int l=0;l<8;l++) state[i][l]=iv[i];
        for (size_t b=0;b<nblocks;b++) {
            uint8_t b8[8][64];
            for (int l=0;l<8;l++) memcpy(b8[l], data + l*nbytes + b*64, 64);
            sha256_8way(state, b8);
        }
    }
    double t1=now();
    double total=8.0*nbytes;
    printf("naive avx2 8way: %.4f s  %.1f MB/s\n", (t1-t0)/reps, total/((t1-t0)/reps)/1e6);
    return 0;
}
EOF
