"  uint w[64];\n"
"  #pragma unroll 16\n"
"  for (int i=0;i<16;i++) w[i]=((uint)bp[i*4]<<24)|((uint)bp[i*4+1]<<16)|((uint)bp[i*4+2]<<8)|((uint)bp[i*4+3]);\n"
