        cl_kernel k=clCreateKernel(prog,"fill",&err);
        printf("  kernel err %d\n", err);
        cl_mem buf=clCreateBuffer(ctx,CL_MEM_WRITE_ONLY,64,NULL,&err);
        cl_uint n=16;
        clSetKernelArg(k,0,sizeof(cl_mem),&buf);
        clSetKernelArg(k,1,sizeof(cl_uint),&n);
        size_t g=16;
        err=clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
        printf("  enq %d\n", err);
        uint32_t host[16]={0};
        err=clEnqueueReadBuffer(q,buf,CL_TRUE,0,64,host,0,NULL,NULL);
